{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table vahdam_db.maplemonk.vahdam_ca_3p_finevents_actuals as with sku_asin as ( select SKU, ASIN from ( select SKU, case when sku = \'Uncommingled.MSKU.1614859309584\' then \'B08Y1FH4ZP\' else ASIN end as ASIN, row_number() over (partition by SKU order by ASIN) rw from (select distinct SKU, ASIN from vahdam_db.maplemonk.ASP_CA_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL where year(\"purchase-date\"::date) >= \'2023\' and sku is not null) ) where rw = 1 ), ship as ( select POSTEDDATE::date as day, SELLERSKU, sum(ifnull(PRINCIPAL,0)) + sum(ifnull(SHIPPINGCHARGE,0)) + sum(ifnull(GIFTWRAP,0)) + sum(ifnull(PROMOTION,0)) + sum(ifnull(GIFTWRAPCHARGEBACK,0)) + sum(ifnull(SHIPPINGCHARGEBACK,0)) as sales_product_net, sum(ifnull(QUANTITY,0)) as qty, sum(ifnull(COMMISSION,0)) + sum(ifnull(FIXEDCLOSINGFEE,0)) + sum(ifnull(VARIABLECLOSINGFEE,0)) + sum(ifnull(SALESTAXCOLLECTIONFEE,0)) + sum(ifnull(DIGITALSERVICESFEE,0)) + sum(ifnull(PANAMERICASCHARGEBACKFEE,0)) as commission, sum(ifnull(FBAPERUNITFULFILLMENTFEE,0)) as last_mile_direct from vahdam_db.maplemonk.vahdam_CA_shipment_event_list where lower(MarketplaceName)=\'amazon.ca\' group by 1,2 ), refund as ( select POSTEDDATE::date as day, SELLERSKU, sum(ifnull(PRINCIPAL,0)) + sum(ifnull(SHIPPINGCHARGE,0)) + sum(ifnull(GIFTWRAP,0)) + sum(ifnull(REFUND_PROMOTION,0)) + sum(ifnull(GIFTWRAPCHARGEBACK,0)) + sum(ifnull(SHIPPINGCHARGEBACK,0)) + sum(ifnull(RETURNSHIPPING,0)) + sum(ifnull(GOODWILL,0)) + sum(ifnull(EXPORTCHARGE,0)) as sales_product_net, -1 * sum(ifnull(QUANTITY,0)) as qty, sum(ifnull(COMMISSION,0)) + sum(ifnull(REFUNDCOMMISSION,0)) + sum(ifnull(SALESTAXCOLLECTIONFEE,0)) + sum(ifnull(DIGITALSERVICESFEE,0)) + sum(ifnull(VARIABLECLOSINGFEE,0)) + sum(ifnull(FIXEDCLOSINGFEE,0)) + sum(ifnull(PANAMERICASCHARGEBACKFEE,0)) as commission, 0 as last_mile_direct from vahdam_db.maplemonk.vahdam_CA_refund_event_list where lower(MarketplaceName)=\'amazon.ca\' group by 1,2 ), adj as ( select PostedDate::date as day, SellerSKU, sum(ifnull(Compensated_Clawback_Total_Amount,0)) + sum(ifnull(WAREHOUSE_DAMAGE_Total_Amount,0)) + sum(ifnull(REVERSAL_REIMBURSEMENT_Total_Amount,0)) + sum(ifnull(WAREHOUSE_LOST_Total_Amount,0)) + sum(ifnull(WAREHOUSE_LOST_MANUAL_Total_Amount,0)) + sum(ifnull(WAREHOUSE_DAMAGE_EXCEPTION_Total_Amount,0)) + sum(ifnull(FREE_REPLACEMENT_REFUND_ITEMS_Total_Amount,0)) + sum(ifnull(MISSING_FROM_INBOUND_Total_Amount,0)) + sum(ifnull(MISSING_FROM_INBOUND_CLAWBACK_Total_Amount,0)) + sum(ifnull(RE_EVALUATION_Total_Amount,0)) + sum(ifnull(MULTICHANNEL_ORDER_LOST_Total_Amount,0)) + sum(ifnull(PAYMENT_RETRACTION_ITEMS_Total_Amount,0)) + sum(ifnull(OTHER_ADJUSTMENT_Total_Amount,0)) as other_sales from vahdam_db.maplemonk.vahdam_ca_adjustment_event_list where Currency = \'CAD\' group by 1,2 ), direct_sku as ( select coalesce(s.day,r.day) as day, coalesce(s.SELLERSKU,r.SELLERSKU) as sku, ifnull(s.sales_product_net,0) + ifnull(r.sales_product_net,0) as sales_product_net, ifnull(s.qty,0) + ifnull(r.qty,0) as units, ifnull(s.commission,0) + ifnull(r.commission,0) as commission, ifnull(s.last_mile_direct,0) + ifnull(r.last_mile_direct,0) as last_mile_direct from ship s full outer join refund r on s.day = r.day and lower(s.SELLERSKU) = lower(r.SELLERSKU) ), direct_asin as ( select d.day, sa.ASIN as asin, sum(d.sales_product_net) as sales_product_net, sum(d.units) as units, sum(d.commission) as commission, sum(d.last_mile_direct) as last_mile_direct from direct_sku d left join sku_asin sa on lower(d.sku) = lower(sa.SKU) group by 1,2 ), adj_asin as ( select a.day, sa.ASIN as asin, sum(a.other_sales) as other_sales from adj a left join sku_asin sa on lower(a.SellerSKU) = lower(sa.SKU) group by 1,2 ), svc_day as ( select Date as day, sum(case when Fee_Type in (\'FBADisposalFee\',\'FBARemovalFee\',\'LabelingFee\',\'FBAInboundDefectFee\') then Amount else 0 end) as lastmile_pool, sum(case when Fee_Type in (\'DealParticipationFee\',\'DealPerformanceFee\',\'CouponParticipationFee\',\'CouponPerformanceFee\',\'VineFee\',\'Subscription\') then Amount else 0 end) as pm_pool, sum(case when Fee_Type = \'AmazonUpstreamProcessingFee\' then Amount else 0 end) as storage_daily_pool from vahdam_db.maplemonk.vahdam_ca_service_fees where Currency = \'CAD\' group by 1 ), storage_month_raw as ( select date_trunc(\'month\', Date) as m, sum(Amount) as amt from vahdam_db.maplemonk.vahdam_ca_service_fees where Currency = \'CAD\' and Fee_Type in (\'FBAStorageFee\',\'FBALongTermStorageFee\',\'STARStorageFee\') group by 1 ), month_spine as (select distinct date_trunc(\'month\', day) as m from direct_asin), storage_used as ( select s.m, coalesce(nullif(cur.amt,0), prev.amt) as storage_amt_used from month_spine s left join storage_month_raw cur on cur.m = s.m left join storage_month_raw prev on prev.m = dateadd(month,-1,s.m) ), day_tot as (select day, sum(sales_product_net) as tot_sales_net from direct_asin group by 1) select da.day, \'Amazon_3P\' as channel, \'CA\' as geo, da.asin, da.units, da.sales_product_net, ifnull(aj.other_sales,0) as other_sales, da.sales_product_net + ifnull(aj.other_sales,0) as sales_net, da.commission, da.last_mile_direct + ifnull(sv.lastmile_pool,0) * div0(da.sales_product_net, dt.tot_sales_net) as last_mile, ifnull(su.storage_amt_used,0) * div0(da.sales_product_net, dt.tot_sales_net) / day(last_day(da.day)) + ifnull(sv.storage_daily_pool,0) * div0(da.sales_product_net, dt.tot_sales_net) as storage, ifnull(sv.pm_pool,0) * div0(da.sales_product_net, dt.tot_sales_net) as pm_fees from direct_asin da left join adj_asin aj on aj.day = da.day and aj.asin = da.asin left join day_tot dt on dt.day = da.day left join svc_day sv on sv.day = da.day left join storage_used su on su.m = date_trunc(\'month\', da.day); create or replace table vahdam_db.maplemonk.vahdam_amazon_pnl_finevents_ca_3p as with asin_map_unpivot as ( select trim(asin) as asin, src, BRAND as brand, \"Common SKU ID\" as common_sku_id, \"Common SKU Description\" as common_sku_description, CATEGORY as category, \"Sub-category\" as sub_category, \"Type-3\" as amz_category from vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING unpivot (asin for src in ( \"Amazon USA\",\"Amazon CA\",\"Amazon DE\",\"Amazon ES\",\"Amazon FR\",\"Amazon IT\", \"Amazon UK\",\"Amazon UAE\",\"Amazon AUS\",\"Amazon JP\",\"Amazon SG\",\"Amazon India\", \"Amazon US 1P\",\"Amazon UK 1P\",\"Amazon EU 1P\",\"Amazon CA 1P\",\"Amazon India 1P\")) where asin is not null and trim(asin) <> \'\' ), asin_geo_map as ( select asin, brand, common_sku_id, common_sku_description, category, sub_category, amz_category, case when src ilike \'%1P\' then \'Amazon_1P\' else \'Amazon_3P\' end as channel, case when upper(src)=\'AMAZON USA\' then \'USA\' when upper(src)=\'AMAZON US 1P\' then \'USA\' when upper(src)=\'AMAZON INDIA\' then \'IN\' when upper(src)=\'AMAZON INDIA 1P\' then \'IN\' else upper(replace(replace(src,\'Amazon \',\'\'),\' 1P\',\'\')) end as geo from asin_map_unpivot where upper(src) <> \'AMAZON EU 1P\' ), asin_geo_map_dedup as ( select asin, channel, geo, any_value(brand) brand, any_value(common_sku_id) common_sku_id, any_value(common_sku_description) common_sku_description, any_value(category) category, any_value(sub_category) sub_category, any_value(amz_category) amz_category from asin_geo_map group by asin, channel, geo ), cogs_sheet as ( select trim(MATERIAL) as common_sku_id, try_to_decimal(replace(COGS,\',\',\'\'),30,5) as cogs_per_unit_inr from vahdam_db.maplemonk.VAHDAM_FY27_INPUTS_COGS_SHEET where MATERIAL is not null ), cogs_budget_csku as ( select trim(\"Common SKU\") as common_sku_id, avg(try_to_decimal(replace(COGS_PER_UNIT,\',\',\'\'),30,5) * try_to_decimal(replace(FX,\',\',\'\'),30,5)) as cogs_per_unit_inr_csku from vahdam_db.maplemonk.VAHDAM_BUDGET_AMAZON_3P___1P_BUDGET where trim(\"Common SKU\") is not null and trim(\"Common SKU\") <> \'\' group by 1 having avg(try_to_decimal(replace(COGS_PER_UNIT,\',\',\'\'),30,5) * try_to_decimal(replace(FX,\',\',\'\'),30,5)) is not null ), budget_raw as ( select trim(ASIN) as asin, trim(\"Common SKU\") as common_sku_id, upper(GEOGRAPHY) as geo, case when upper(PLATFORM) like \'%1P%\' then \'Amazon_1P\' when upper(PLATFORM) like \'%3P%\' then \'Amazon_3P\' else PLATFORM end as channel, try_to_date(\"MONTH\",\'DD-Mon-YY\') as month_start, try_to_decimal(replace(FX,\',\',\'\'),30,5) as fx, try_to_decimal(replace(QTY,\',\',\'\'),30,5) as qty, try_to_decimal(replace(\"Net Sales\",\',\',\'\'),30,5) as net_sales, try_to_decimal(replace(COGS,\',\',\'\'),30,5) as cogs, try_to_decimal(replace(\"Additional Duty\",\',\',\'\'),30,5) as additional_duty, try_to_decimal(replace(COMMISSION,\',\',\'\'),30,5) as commission, try_to_decimal(replace(OUTBOUND,\',\',\'\'),30,5) as outbound, try_to_decimal(replace(\"3PL\",\',\',\'\'),30,5) as three_pl, try_to_decimal(replace(STORAGE,\',\',\'\'),30,5) as storage, try_to_decimal(replace(\"Last mile\",\',\',\'\'),30,5) as last_mile, try_to_decimal(replace(\"Performance Marketing\",\',\',\'\'),30,5) as performance_marketing, try_to_decimal(replace(COGS_PER_UNIT,\',\',\'\'),30,5) as cogs_per_unit_local, try_to_decimal(replace(OUTBOUND_PER_UNIT,\',\',\'\'),30,5) as outbound_per_unit_local, try_to_decimal(replace(\"3pl_per_unit\",\',\',\'\'),30,5) as three_pl_per_unit_local, try_to_decimal(replace(STORAGE_PER_UNIT,\',\',\'\'),30,5) as storage_per_unit_local, try_to_decimal(replace(LASTMILE_PER_UNIT,\',\',\'\'),30,5) as lastmile_per_unit_local, try_to_decimal(replace(COMMISSION_PER_UNIT,\',\',\'\'),30,5) as commission_per_unit_local, try_to_decimal(replace(ADDITIONAL_DUTY_PER_UNIT,\',\',\'\'),30,5) as additional_duty_per_unit_local from vahdam_db.maplemonk.VAHDAM_BUDGET_AMAZON_3P___1P_BUDGET ), fx_map as (select geo, month_start, max(fx) fx from budget_raw where fx is not null and month_start is not null group by 1,2), fx_geo_avg as (select geo, avg(fx) fx_geo_avg from fx_map group by 1), budget_asin as ( select geo, channel, month_start, asin, any_value(common_sku_id) common_sku_id, max(fx) fx, sum(qty) qty, sum(net_sales) net_sales_local, sum(cogs) cogs_local, sum(additional_duty) additional_duty_local, sum(commission) commission_local, sum(outbound) outbound_local, sum(three_pl) three_pl_local, sum(storage) storage_local, sum(last_mile) last_mile_local, sum(performance_marketing) pm_spend_local, avg(cogs_per_unit_local) cogs_per_unit_local, avg(outbound_per_unit_local) outbound_per_unit_local, avg(three_pl_per_unit_local) three_pl_per_unit_local, avg(storage_per_unit_local) storage_per_unit_local, avg(lastmile_per_unit_local) lastmile_per_unit_local, avg(commission_per_unit_local) commission_per_unit_local, avg(additional_duty_per_unit_local) additional_duty_per_unit_local, case when coalesce(sum(additional_duty),0) > 0 or coalesce(avg(additional_duty_per_unit_local),0) > 0 then 1 else 0 end as has_additional_duty_flag from budget_raw where month_start is not null and asin is not null group by geo, channel, month_start, asin ), budget_pkg as ( select geo, channel, month_start, left(common_sku_id,6) pkg6, any_value(outbound_per_unit_local) outbound_per_unit_local_pkg, any_value(three_pl_per_unit_local) three_pl_per_unit_local_pkg from budget_raw where month_start is not null and common_sku_id is not null and length(common_sku_id) >= 6 group by geo, channel, month_start, left(common_sku_id,6) ), budget_asin_anychannel as ( select geo, month_start, asin, avg(outbound_per_unit_local) outbound_per_unit_local_xc, avg(three_pl_per_unit_local) three_pl_per_unit_local_xc from budget_raw where month_start is not null and asin is not null group by 1,2,3 ), budget_pkg_anychannel as ( select geo, month_start, left(common_sku_id,6) pkg6, any_value(outbound_per_unit_local) outbound_per_unit_local_pkg_xc, any_value(three_pl_per_unit_local) three_pl_per_unit_local_pkg_xc from budget_raw where month_start is not null and common_sku_id is not null and length(common_sku_id) >= 6 group by geo, month_start, left(common_sku_id,6) ), budget_days as (select month_start, day(last_day(month_start)) days_in_month from (select distinct month_start from budget_raw where month_start is not null)), day_offsets as (select seq4() d_off from table(generator(rowcount => 31))), budget_daily as ( select dateadd(day,o.d_off,b.month_start) as day, b.channel, b.geo, b.asin, b.qty/nullif(d.days_in_month,0) qty_budget, b.net_sales_local/nullif(d.days_in_month,0) sales_budget_local, b.cogs_local/nullif(d.days_in_month,0) cogs_budget_local, b.additional_duty_local/nullif(d.days_in_month,0) additional_duty_budget_local, b.commission_local/nullif(d.days_in_month,0) commission_budget_local, b.outbound_local/nullif(d.days_in_month,0) outbound_budget_local, b.three_pl_local/nullif(d.days_in_month,0) three_pl_budget_local, b.storage_local/nullif(d.days_in_month,0) storage_budget_local, b.last_mile_local/nullif(d.days_in_month,0) last_mile_budget_local, b.pm_spend_local/nullif(d.days_in_month,0) pm_spend_budget_local from budget_asin b join budget_days d on d.month_start=b.month_start join day_offsets o on o.d_off<d.days_in_month where b.geo=\'CA\' and b.channel=\'Amazon_3P\' ), pm_actuals as ( select DAY as day, upper(GEO) geo, ASIN as asin, sum(SPEND) pm_spend_actual_local, sum(GOOGLE_SPEND) google_spend_actual_local from vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING where upper(GEO)=\'CA\' and upper(MARKETPLACE)=\'AMAZON_3P\' group by 1,2,3 ), tool_cost_monthly as ( select try_to_date(MONTH,\'MM-DD-YYYY\') month_start, sum(try_to_decimal(replace(\"Spend(INR)\",\',\',\'\'),30,5)) tool_cost_total_inr from vahdam_db.maplemonk.fy27_inputs_tool_cost where upper(BUSINESS)=\'AMAZON\' and try_to_date(MONTH,\'MM-DD-YYYY\') is not null group by 1 ), fe as ( select f.* from vahdam_db.maplemonk.vahdam_ca_3p_finevents_actuals f where f.day >= (select min(month_start) from budget_raw where month_start is not null) ), universe as ( select day, channel, geo, asin from fe union select day, channel, geo, asin from budget_daily ), asin_resolved as ( select u.day,u.channel,u.geo,u.asin, m.brand,m.common_sku_id,m.common_sku_description,m.category,m.sub_category,m.amz_category, left(m.common_sku_id,6) pkg6 from universe u left join asin_geo_map_dedup m on m.asin=u.asin and m.channel=u.channel and m.geo=u.geo ), pass1 as ( select u.day,u.channel,u.geo,u.asin, ar.brand,ar.common_sku_id,ar.common_sku_description,ar.category,ar.sub_category,ar.amz_category,ar.pkg6, date_trunc(\'month\',u.day) month_start, coalesce(fxm.fx,fxg.fx_geo_avg) fx_inr, f.units as qty_actual, f.sales_net as sales_actual_local, f.other_sales, f.commission as commission_signed, f.last_mile as last_mile_signed, f.storage as storage_signed, f.pm_fees as pm_fees_signed, pa.pm_spend_actual_local, pa.google_spend_actual_local, coalesce(cbc.cogs_per_unit_inr_csku, cs.cogs_per_unit_inr*1.05) cogs_per_unit_inr_p1, coalesce(ba.outbound_per_unit_local, bp.outbound_per_unit_local_pkg, baxc.outbound_per_unit_local_xc, bpxc.outbound_per_unit_local_pkg_xc) outbound_per_unit_local_p1, coalesce(ba.three_pl_per_unit_local, bp.three_pl_per_unit_local_pkg, baxc.three_pl_per_unit_local_xc, bpxc.three_pl_per_unit_local_pkg_xc) three_pl_per_unit_local_p1, coalesce(ba.has_additional_duty_flag,0) has_additional_duty_flag, bd.qty_budget,bd.sales_budget_local,bd.cogs_budget_local,bd.additional_duty_budget_local,bd.commission_budget_local, bd.outbound_budget_local,bd.three_pl_budget_local,bd.storage_budget_local,bd.last_mile_budget_local,bd.pm_spend_budget_local from universe u left join asin_resolved ar on ar.day=u.day and ar.channel=u.channel and ar.geo=u.geo and ar.asin=u.asin left join fe f on f.day=u.day and f.channel=u.channel and f.geo=u.geo and f.asin=u.asin left join pm_actuals pa on pa.day=u.day and pa.geo=u.geo and pa.asin=u.asin left join budget_daily bd on bd.day=u.day and bd.channel=u.channel and bd.geo=u.geo and bd.asin=u.asin left join cogs_sheet cs on cs.common_sku_id=ar.common_sku_id left join cogs_budget_csku cbc on cbc.common_sku_id=ar.common_sku_id left join fx_map fxm on fxm.geo=u.geo and fxm.month_start=date_trunc(\'month\',u.day) left join fx_geo_avg fxg on fxg.geo=u.geo left join budget_asin ba on ba.geo=u.geo and ba.channel=u.channel and ba.month_start=date_trunc(\'month\',u.day) and ba.asin=u.asin left join budget_pkg bp on bp.geo=u.geo and bp.channel=u.channel and bp.month_start=date_trunc(\'month\',u.day) and bp.pkg6=ar.pkg6 left join budget_asin_anychannel baxc on baxc.geo=u.geo and baxc.month_start=date_trunc(\'month\',u.day) and baxc.asin=u.asin left join budget_pkg_anychannel bpxc on bpxc.geo=u.geo and bpxc.month_start=date_trunc(\'month\',u.day) and bpxc.pkg6=ar.pkg6 ), actuals_pct as ( select geo, channel, month_start, case when sum(case when cogs_per_unit_inr_p1 is not null and qty_actual is not null then sales_actual_local*fx_inr end) > 0 then sum(case when cogs_per_unit_inr_p1 is not null and qty_actual is not null then qty_actual*cogs_per_unit_inr_p1 end) / nullif(sum(case when cogs_per_unit_inr_p1 is not null and qty_actual is not null then sales_actual_local*fx_inr end),0) end as cogs_pct, case when sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end) > 0 then sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then qty_actual*outbound_per_unit_local_p1 end) / nullif(sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end),0) end as outbound_pct, case when sum(case when three_pl_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end) > 0 then sum(case when three_pl_per_unit_local_p1 is not null and qty_actual is not null then qty_actual*three_pl_per_unit_local_p1 end) / nullif(sum(case when three_pl_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end),0) end as three_pl_pct from pass1 group by 1,2,3 ), actuals_pct_geo as ( select geo, month_start, case when sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end) > 0 then sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then qty_actual*outbound_per_unit_local_p1 end) / nullif(sum(case when outbound_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end),0) end as outbound_pct_g, case when sum(case when three_pl_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end) > 0 then sum(case when three_pl_per_unit_local_p1 is not null and qty_actual is not null then qty_actual*three_pl_per_unit_local_p1 end) / nullif(sum(case when three_pl_per_unit_local_p1 is not null and qty_actual is not null then sales_actual_local end),0) end as three_pl_pct_g from pass1 group by 1,2 ), pass1b as ( select p.* replace ( coalesce(p.cogs_per_unit_inr_p1, p.sales_actual_local*p.fx_inr*ap.cogs_pct/nullif(p.qty_actual,0)) as cogs_per_unit_inr_p1, coalesce(p.outbound_per_unit_local_p1, p.sales_actual_local*ap.outbound_pct/nullif(p.qty_actual,0), p.sales_actual_local*apg.outbound_pct_g/nullif(p.qty_actual,0)) as outbound_per_unit_local_p1, coalesce(p.three_pl_per_unit_local_p1, p.sales_actual_local*ap.three_pl_pct/nullif(p.qty_actual,0), p.sales_actual_local*apg.three_pl_pct_g/nullif(p.qty_actual,0)) as three_pl_per_unit_local_p1 ) from pass1 p left join actuals_pct ap on ap.geo=p.geo and ap.channel=p.channel and ap.month_start=p.month_start left join actuals_pct_geo apg on apg.geo=p.geo and apg.month_start=p.month_start ), tool_alloc as ( select month_start, sum(ifnull(sales_actual_local,0)*ifnull(fx_inr,0)) total_sales_inr_month from pass1 group by 1 ), global_tool_denom as ( select date_trunc(\'month\',sm.DAY) month_start, sum(sm.SALES*fxm.fx) global_sales_inr from vahdam_db.maplemonk.VAHDAM_AMAZON_SALES_MARKETING sm join fx_map fxm on fxm.geo=upper(sm.GEO) and fxm.month_start=date_trunc(\'month\',sm.DAY) where upper(sm.MARKETPLACE)=\'AMAZON_3P\' group by 1 ) s